-- Codex items batch (locked 2026-10-22, rev 1:19 PM MT). 172 rows. Idempotent upsert on lower(name).
BEGIN;
ALTER TABLE items ADD COLUMN IF NOT EXISTS item_subtype text NULL;
ALTER TABLE items DROP CONSTRAINT IF EXISTS items_subtype_check;
ALTER TABLE items ADD CONSTRAINT items_subtype_check CHECK ((item_category='potion' AND item_subtype IN ('health','stat','spell','poison','bomb')) OR (item_category='magical_item' AND item_subtype IN ('ring','necklace','gem','miscellaneous','unique')) OR (item_category IN ('spell_scroll','common_item') AND item_subtype IS NULL));
COMMIT;
